/* int8 knock-detector MLP on the Vortex-V Xmlacc unit (M9). Contract: ml/knock/golden.py.
 * Weights: gen/knock_weights.h, generated by `python -m ml.knock.export` from the committed
 * ml/policies/knock_int8.json. */
#ifndef KNOCK_KERNEL_H
#define KNOCK_KERNEL_H

#include <stdint.h>

#include "knock_weights.h"      /* KNOCK_N_IN and the layer tables */

/* x: KNOCK_N_IN int8 accelerometer samples, 8-byte aligned. Returns the int32 output accumulator
 * (the logit in units of KNOCK_LOGIT_SCALE); knock is declared when it exceeds KNOCK_THRESHOLD_Q. */
int32_t knock_infer(const int8_t *x);

#endif
